function d_grid_balance(P,R){var dem=P.demand_MW||[400,450,500,420,380],gen=P.gen_MW||[420,430,480,440,400];var stor=0,cap=P.storage_MWh||200,unmet=0;for(var i=0;i<dem.length;i++){var net=gen[i]-dem[i];stor=Math.max(0,Math.min(cap,stor+net));if(net<0&&stor<=0)unmet+=-(net);}return{hours:dem.length,unmet_MWh:+unmet.toFixed(1),storage_used_MWh:+stor.toFixed(1),balanced:unmet===0};}

